;#############################################################################################################
;# yi/SuperFX/Banks/Bank4D.asm -- SuperFX data bank $4D ($4D:0000-$4D:FFFF, 64 KB).
;#
;# Notable interior addresses (observed):
;#   $4D:0000  enemy-object data pointer table head
;#   $4D:048A  per-enemy "special character address" table
;#   $4D:0914  per-enemy sprite-pointer table
;#
;# NOTE re external references: SMW Central's memory map describes a single
;# "MAP16 page tables" region spanning `$18:B3F2`-`$1A:D619` (74 KB), which
;# would extend into this bank up to `$4D:5619`. That claim is over-broad --
;# Map16 page tables actually end at `$4C:D619` (~41 KB; see Bank4C header).
;# Bank4D from `$4D:0000` onward is enemy-data pointer tables + asset payloads
;# as documented here, NOT Map16 tile data. The byte pattern at `$4D:0000`
;# (sparse `$09xx` pointers among `$0000` empties) confirms the pointer-table
;# interpretation; SMWC mis-categorised these bytes.
;#
;# Bank4D opens with a dense 16-bit pointer table (one dw per enemy ID).
;# Most entries are $0000 (no asset for that ID); populated entries point
;# at DATA_4D09xx labels later in the same bank where the actual
;# per-enemy character / animation / OAM tables live.
;#
;# This bank is purely DATA -- no executable SuperFX code. The 65816 reads
;# bytes from here via SuperFX-RAM-mapping (during the GSU's idle phase)
;# and the SuperFX rasterisers in Bank0A/0B read it via GETB(R14) in
;# RAMB-then-ROMB switches.
;#
;# Contents at a glance:
;#   $4D:0000 DATA_enemy_object_data_ptrs    -- per-enemy primary asset pointer table
;#   $4D:048A DATA_enemy_special_chr_addrs   -- per-enemy special character addresses
;#   $4D:0914 DATA_enemy_sprite_ptrs         -- per-enemy sprite pointer table
;#   $4D:09E4..                         -- DATA_4D09E4 onwards: actual asset payloads
;#                                         (8x8 / 16x16 / 32x32 character data,
;#                                         animation frame tables, OAM-fragment tables).
;#
;# See also:
;#   chip/ys_chip0.asm through chip/ys_chip7.asm  -- chip program files whose data-driving
;#                                                   routines consume these enemy tables
;#   chip/Gdefchr.asm                             -- global character defs
;#
;# Cross-references:
;#   yi/SuperFX/RoutinePointers.asm                  -- pointer-table entries (DATA_4D*)
;#   docs/mchip.md                          -- standalone SuperFX reference
;#############################################################################################################

%SuperFXBankStart(!FXBank4D)

